lemma.raw:
\label{nondeg}
Let $V$ be a reduced, equidimensional, non-degenerate subvariety of $ \ensuremath{\mathbb{P}}^n$ ($n \geq 4$) of codimension 2 (not necessarily irreducible). 
Let $H$ be a general hyperplane and let $W = V \cap H$. Then $W$ is non-degenerate in $H =  \ensuremath{\mathbb{P}}^{n-1}$.

proposition.raw:
\label{SLPvUH}
Let $L_1,\ldots, L_r$ be distinct linear forms on $ \ensuremath{\mathbb{P}}^n$, and let $Z$ be the set
of points in $ \ensuremath{\mathbb{P}}^n$ dual to the hyperplanes defined by the $L_i$. Fix integers $d\geq m>1$.
Then the following are equivalent:
\begin{enumerate}
\item[(a)] $Z$ has an unexpected hypersurface of degree $d$ with a general point $P$ of multiplicity~$m$;
\item[(b)] $R/(L_1^{d},\ldots, L_r^{d})$ fails SLP in degree $i=m-1$ with range $k=d-m+1$.
\end{enumerate}

corollary.raw:
\label{WLP Pn cons}
Let $n \geq 4$ and $k \geq 3$. Set 
\[
f(n, k) = \begin{cases}
\binom{n+k}{n} - \binom{n+k-2}{n} - \binom{n + \frac{k}{2}}{n} + \binom{n -2 + \frac{k}{2}}{n} & \text{ if $k$ is even} \\
\binom{n+k}{n} - \binom{n+k-2}{n} - 2 \binom{n + \frac{k-1}{2}}{n} +  2 \binom{n + \frac{k-3}{2}}{n-1} & \text{ if $k$ is odd.}
\end{cases}
\]
Choose any integer $N \geq f(n,k)$. Then there exist linear forms $L_1,\dots,L_N \in  \ensuremath{\mathbb{K}}[x_0,\dots,x_n] = R$ satisfying

\begin{itemize}

\item no $n+1$ of the linear forms have a common zero, and

\item $R/(L_1^k,\dots,L_N^k)$ fails the WLP from degree $k-1$ to degree $k$.

\end{itemize}

remark.raw:
\begin{enumerate}
\item Note that Corollary \ref{fail SLP} (and similarly for the earlier results) is not necessarily about failure of surjectivity. The proof only 
shows that the cokernel of $\times L^{d-m+1}$ is bigger than expected, which means failure of surjectivity if $\dim [R/I]_{m-1} \geq \dim [R/I]_d$, and it means failure of injectivity if $\dim [R/I]_{m-1} \leq \dim [R/I]_d$.

\item In \cite{SS}, Schenck and Seceleanu proved the striking result that for {\em every} ideal of the form $I = (L_1^{a_1},\dots,L_e^{a_e})$ in the ring $ \ensuremath{\mathbb{K}}[x,y,z]$, the quotient $R/I$ has the WLP. In the case that all $a_i$ are equal to some $d$, we can recover this result from Corollary \ref{fail SLP}. Indeed, this is the case $n=2$. Checking whether WLP holds amounts to considering the case $m=d$ (since we are studying $\times L^1$), and Corollary \ref{fail SLP} says that in this case maximal rank always holds.

\end{enumerate}

